import { type Item } from "./price-list.js";

/** What one damaged item lost in an incident, as the claim report states it. */
export interface Damage {
  itemType: string;
  amount: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;

/**
 * The share of a damage the MHPCO carries before the deductible. The office's
 * special clauses read the damaged item's own attributes -- enchantment level and
 * material -- so the covered share is decided per damaged item, not per incident.
 * With no clause in force the office reimburses in full. Both clauses are still
 * driven by inactive tests.
 */
function coveredShareOf(_damagedItem: Item | undefined): number {
  return 1;
}

/**
 * The deductible is charged per damage event, so an incident that harms two items
 * is reduced twice. What the office carries and what the customer bears are two
 * separate decisions applied in that order.
 */
function reimbursementFor(damage: Damage, damagedItem: Item | undefined): number {
  return damage.amount * coveredShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
}

/** The insured item a damage report points at, looked up by the type it names. */
function damagedItemOf(items: Item[], damage: Damage): Item | undefined {
  return items.find((item) => item.type === damage.itemType);
}

export function payoutFor(items: Item[], damages: Damage[]): number {
  return damages.reduce(
    (payout, damage) => payout + reimbursementFor(damage, damagedItemOf(items, damage)),
    0,
  );
}
